/**
 * The instance's VAPID key pair (spec §4.3 "nothing per channel"): generated by the instance
 * the first time it is needed — a page offering to subscribe a device, or a send — sealed
 * under the master key in `instance_config` (`notifications.vapid`, so the master-key re-seal
 * and the boot's probe cover it with every other instance secret). Nothing to configure.
 *
 * Not at the boot: a command that builds a root on the store (the v4 import's dry run, say)
 * must write nothing. Generation is single-flight in the process.
 *
 * The pair never changes by itself: a new pair would make every stored subscription
 * useless (each browser subscribed with the public half). A pair that does not open (a
 * master key that does not fit) is not replaced either: replacing it would drop every
 * device for what is a configuration error the boot already reports.
 */
import type { ConfigRepo } from '../store/repositories/config';
import {
  generateVapidKeys,
  parseVapidKeys,
  vapidPublicKey,
  type VapidKeys,
} from './web-push/vapid';

export const VAPID_KEYS_KEY = 'notifications.vapid';

export interface VapidKeyStore {
  /** The pair; generated and sealed when the store holds none. */
  keys(): Promise<VapidKeys>;
  /** What a browser subscribes with (`applicationServerKey`), base64url; `null` when unreadable. */
  publicKey(): Promise<string | null>;
}

export function createVapidKeyStore(
  config: Pick<ConfigRepo, 'getSecret' | 'setSecret' | 'keys'>,
): VapidKeyStore {
  const readOrCreate = async (): Promise<VapidKeys> => {
    if (!(await config.keys()).includes(VAPID_KEYS_KEY)) {
      await config.setSecret(VAPID_KEYS_KEY, JSON.stringify(generateVapidKeys()));
    }
    const stored = await config.getSecret(VAPID_KEYS_KEY);
    if (stored === null) throw new Error('the VAPID key pair was not stored');
    return parseVapidKeys(stored);
  };
  // single-process only: one promise per process; read once and kept, the pair never changes.
  let pending: Promise<VapidKeys> | null = null;
  const keys = (): Promise<VapidKeys> => {
    pending ??= readOrCreate().catch((err: unknown) => {
      pending = null;
      throw err;
    });
    return pending;
  };
  return {
    keys,
    async publicKey() {
      try {
        return vapidPublicKey(await keys());
      } catch {
        return null;
      }
    },
  };
}
